test.describe("Authentication", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/login");
    await page.getByTestId("login-email").fill("alex@freelance.dev");
    await page.getByTestId("login-password").fill("Str0ngPass99");
    await page.getByRole("button", { name: "Sign in" }).click();
  });

  test("Freelancer signs up with valid email and password", async ({ page }) => {
    // covers FIT-FUNC-001
    const pom = new LoginPage(page);
    await pom.goto();
    // Given: a new freelancer on the signup screen
    // When: they provide alex@freelance.dev and Str0ngPass99 with digits
    await expect(page.getByTestId("status-fit-func-001")).toBeVisible();
    // Then: the account is created and the user is authenticated
    await expect(page.getByTestId("result-fit-func-001")).toContainText("Account created and dashboard accessible");
  });

  test("Password boundary 7/8 and 64/65 characters", async ({ page }) => {
    // covers FIT-BND-001
    const pom = new LoginPage(page);
    await pom.goto();
    // Given: the freelancer registration form
    // When: testing 7 chars (Passw1!), 8 chars (Passw0rd), 64 chars, and 65 chars
    await expect(page.getByTestId("status-fit-bnd-001")).toBeVisible();
    // Then: 7 and 65 are rejected; 8 and 64 are accepted
    await expect(page.getByTestId("result-fit-bnd-001")).toContainText("Min 8 and Max 64 password length enforce");
  });

  test("6th failed login inside 10 minutes locks account for 15 minutes", async ({ page }) => {
    // covers FIT-SEC-001
    const pom = new LoginPage(page);
    await pom.goto();
    // Given: an account with 5 consecutive failed login attempts in 10 minutes
    // When: a 6th failed login attempt is submitted
    await expect(page.getByTestId("status-fit-sec-001")).toBeVisible();
    // Then: the account is locked for 15 minutes and further login attempts return 423 Locked
    await expect(page.getByTestId("result-fit-sec-001")).toContainText("Account locked for 15 minutes on 6th fai");
  });

  test("Session invalidation after 60 minutes of inactivity", async ({ page }) => {
    // covers FIT-SEC-002
    const pom = new LoginPage(page);
    await pom.goto();
    // Given: an active session idle for 60 minutes
    // When: any API request is made
    await expect(page.getByTestId("status-fit-sec-002")).toBeVisible();
    // Then: the session is terminated and user is redirected to login with 401
    await expect(page.getByTestId("result-fit-sec-002")).toContainText("Session expires at 60 minutes inactivity");
  });

});

