    // When: they add 2 items (Design 10h @ $100.00 and QA 5h @ $80.00)
    await expect(page.getByTestId("status-fit-func-003")).toBeVisible();
    // Then: total computes to $1,400.00 and invoice number INV-2026-0001 is generated
    await expect(page.getByTestId("result-fit-func-003")).toContainText("Invoice created in Draft status with tot");
  });

  test("Sending invoice generates public link with 32-char token", async ({ page }) => {
    // covers FIT-FUNC-004
    const pom = new InvoiceEditorPage(page);
    await pom.goto();
    // Given: a Draft invoice INV-2026-0001
    // When: the freelancer clicks Send Invoice
    await expect(page.getByTestId("status-fit-func-004")).toBeVisible();
    // Then: status becomes Sent and an email is queued with an unguessable 32-char public link
    await expect(page.getByTestId("result-fit-func-004")).toContainText("Invoice status Sent; 32-char public toke");
  });

  test("Sequential invoice numbering never reuses cancelled number", async ({ page }) => {
    // covers FIT-FUNC-010
    const pom = new InvoiceEditorPage(page);
    await pom.goto();
    // Given: invoice INV-2026-0002 cancelled by the freelancer
    // When: they create the next invoice
    await expect(page.getByTestId("status-fit-func-010")).toBeVisible();
    // Then: the new invoice is assigned INV-2026-0003 and 0002 is never reused
    await expect(page.getByTestId("result-fit-func-010")).toContainText("Next number INV-2026-0003 generated sequ");
  });

  test("Line item quantity boundary 0/1 and 999/1000", async ({ page }) => {
    // covers FIT-BND-003
