    await pom.goto();
    // Given: an invoice line item
    // When: entering quantity 0, 1, 999, and 1000
    await expect(page.getByTestId("status-fit-bnd-003")).toBeVisible();
    // Then: 0 and 1000 are rejected; 1 and 999 are accepted
    await expect(page.getByTestId("result-fit-bnd-003")).toContainText("Quantity range 1–999 enforced");
  });

