    await expect(page.getByTestId("status-fit-bnd-004")).toBeVisible();
    // Then: 0.00 and 1000000.01 are rejected; 0.01 and 1000000.00 are accepted
    await expect(page.getByTestId("result-fit-bnd-004")).toContainText("Unit price range 0.01–1,000,000.00 enfor");
  });

  test("Line items count boundary 50 vs 51 items", async ({ page }) => {
    // covers FIT-BND-005
    const pom = new InvoiceEditorPage(page);
    await pom.goto();
    // Given: an invoice with 50 line items attached
    // When: the freelancer attempts to add a 51st line item
    await expect(page.getByTestId("status-fit-bnd-005")).toBeVisible();
    // Then: the 50 items save successfully but the 51st is blocked with limit error
    await expect(page.getByTestId("result-fit-bnd-005")).toContainText("Max 50 line items enforced");
  });

  test("Note length boundary 500 vs 501 characters", async ({ page }) => {
    // covers FIT-BND-006
