    await expect(page.getByTestId("status-fit-bnd-007")).toBeVisible();
    // Then: 180 days is accepted; 181 days is rejected
    await expect(page.getByTestId("result-fit-bnd-007")).toContainText("Due date max 180 days enforced");
  });

