    await expect(page.getByTestId("status-fit-neg-003")).toBeVisible();
    // Then: validation error blocks save stating due date must be on or after issue date
    await expect(page.getByTestId("result-fit-neg-003")).toContainText("Due date before issue date rejected");
  });

